        CREATE TABLE strains (
            id BIGSERIAL PRIMARY KEY,
            strain_id VARCHAR(255) NOT NULL,
            gene_seq TEXT NOT NULL,
            country_id INTEGER REFERENCES countries(id),
            region_id INTEGER REFERENCES regions(id),
