            drug_resistance_id INTEGER REFERENCES drug_resistances(id),
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            CONSTRAINT unique_strain UNIQUE (strain_id)
        );
        
