            IF 'Mexico City' != '' THEN
                SELECT r.id INTO rid 
                FROM regions r 
                JOIN countries c ON r.country_id = c.id 
                WHERE r.name = 'Mexico City' AND c.name = 'Singapore';
            END IF;
            
            -- Get disease ID
            SELECT id INTO did FROM diseases WHERE name = 'Gastritis';
            
            -- Get drug resistance ID
            SELECT id INTO drid FROM drug_resistances WHERE name = 'TRIPHOSPHATE';
            
            -- Insert strain
            INSERT INTO strains (strain_id, gene_seq, country_id, region_id, disease_id, drug_resistance_id)
            VALUES ('CG22385', '', cid, rid, did, drid)
            ON CONFLICT (strain_id) DO UPDATE SET
                gene_seq = EXCLUDED.gene_seq,
                country_id = EXCLUDED.country_id,
                region_id = EXCLUDED.region_id,
                disease_id = EXCLUDED.disease_id,
                drug_resistance_id = EXCLUDED.drug_resistance_id
            RETURNING id INTO sid;
        END $$;
        

